// Package auth 提供管理员凭据校验与内存会话 token 的签发/校验。
package auth

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"sync"
	"time"
)

// Manager 持有管理员凭据与内存会话表。零值不可用，请用 NewManager 构造。
type Manager struct {
	username string
	password string
	ttl      time.Duration

	mu       sync.Mutex
	sessions map[string]time.Time // token -> 过期时刻
}

// NewManager 用给定凭据构造 Manager；ttl 是每个会话 token 的有效期。
func NewManager(username, password string, ttl time.Duration) *Manager {
	return &Manager{
		username: username,
		password: password,
		ttl:      ttl,
		sessions: make(map[string]time.Time),
	}
}

// Authenticate 校验用户名与密码是否匹配，比较是常数时间的。
func (m *Manager) Authenticate(username, password string) bool {
	userOK := subtle.ConstantTimeCompare([]byte(username), []byte(m.username)) == 1
	passOK := subtle.ConstantTimeCompare([]byte(password), []byte(m.password)) == 1
	return userOK && passOK
}

// Username 返回管理员用户名。
func (m *Manager) Username() string { return m.username }

// Issue 签发一个新的会话 token 并记录其有效期。
func (m *Manager) Issue() string {
	token := randomToken()
	m.mu.Lock()
	defer m.mu.Unlock()
	m.sessions[token] = time.Now().Add(m.ttl)
	return token
}

// Valid 报告 token 是否存在且未过期；过期的 token 会被顺带清掉。
func (m *Manager) Valid(token string) bool {
	if token == "" {
		return false
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	expiresAt, ok := m.sessions[token]
	if !ok {
		return false
	}
	if time.Now().After(expiresAt) {
		delete(m.sessions, token)
		return false
	}
	return true
}

// randomToken 生成 256 位的不透明 token。
func randomToken() string {
	buf := make([]byte, 32)
	if _, err := rand.Read(buf); err != nil {
		// crypto/rand 在正常系统上不会失败；失败意味着无法安全签发会话。
		panic("auth: 无法生成随机 token: " + err.Error())
	}
	return hex.EncodeToString(buf)
}

package auth

import (
	"testing"
	"time"
)

func TestAuthenticate(t *testing.T) {
	m := NewManager("admin", "secret", time.Hour)

	if !m.Authenticate("admin", "secret") {
		t.Fatal("正确凭据应通过校验")
	}
	if m.Authenticate("admin", "wrong") {
		t.Fatal("错误密码不应通过校验")
	}
	if m.Authenticate("root", "secret") {
		t.Fatal("错误用户名不应通过校验")
	}
}

func TestIssueAndValidate(t *testing.T) {
	m := NewManager("admin", "secret", time.Hour)

	if m.Valid("") {
		t.Fatal("空 token 不应有效")
	}
	if m.Valid("not-a-real-token") {
		t.Fatal("未签发的 token 不应有效")
	}

	token := m.Issue()
	if token == "" {
		t.Fatal("Issue 应返回非空 token")
	}
	if !m.Valid(token) {
		t.Fatal("刚签发的 token 应有效")
	}
	if m.Valid(token + "x") {
		t.Fatal("被篡改的 token 不应有效")
	}
}

func TestExpiredToken(t *testing.T) {
	m := NewManager("admin", "secret", -time.Second) // 签发即过期
	token := m.Issue()

	if m.Valid(token) {
		t.Fatal("过期 token 不应有效")
	}
}

// Package server 提供后台管理系统的 HTTP 路由与处理器。
package server

import (
	"encoding/json"
	"io"
	"net/http"
	"strings"

	"admin/internal/auth"
)

// maxBodyBytes 限制登录等 JSON 请求体的大小，避免无界读取。
const maxBodyBytes = 1 << 20

// Server 组装路由并持有依赖。零值不可用，请用 New 构造。
type Server struct {
	auth *auth.Manager
	mux  *http.ServeMux
}

// New 用给定依赖构造 Server 并注册路由。
func New(a *auth.Manager) *Server {
	s := &Server{auth: a, mux: http.NewServeMux()}
	s.routes()
	return s
}

// ServeHTTP 让 Server 满足 http.Handler。
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	s.mux.ServeHTTP(w, r)
}

func (s *Server) routes() {
	s.mux.HandleFunc("/healthz", s.handleHealth)
	s.mux.HandleFunc("/api/v1/login", s.handleLogin)
	s.mux.Handle("/api/v1/", s.requireAuth(http.HandlerFunc(s.handleAPI)))
}

// handleHealth 是无需鉴权的健康检查。
func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

// handleLogin 校验管理员凭据并签发 bearer token。
func (s *Server) handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
		return
	}
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(io.LimitReader(r.Body, maxBodyBytes)).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid request body"})
		return
	}
	if !s.auth.Authenticate(req.Username, req.Password) {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid credentials"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"token": s.auth.Issue()})
}

// handleAPI 分发已通过鉴权的 /api/v1 请求。
func (s *Server) handleAPI(w http.ResponseWriter, r *http.Request) {
	switch r.URL.Path {
	case "/api/v1/me":
		s.handleMe(w, r)
	default:
		http.NotFound(w, r)
	}
}

// handleMe 返回当前登录的管理员身份。
func (s *Server) handleMe(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"username": s.auth.Username()})
}

// requireAuth 是校验 bearer token 的中间件，未通过一律 401。
func (s *Server) requireAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !s.auth.Valid(bearerToken(r)) {
			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
			return
		}
		next.ServeHTTP(w, r)
	})
}

// bearerToken 从 Authorization 头取出 bearer token，取不到返回空串。
func bearerToken(r *http.Request) string {
	const prefix = "Bearer "
	header := r.Header.Get("Authorization")
	if len(header) <= len(prefix) || !strings.EqualFold(header[:len(prefix)], prefix) {
		return ""
	}
	return strings.TrimSpace(header[len(prefix):])
}

// writeJSON 以 JSON 写出响应。
func writeJSON(w http.ResponseWriter, status int, payload any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(payload)
}

package server

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"admin/internal/auth"
)

func newTestServer() *Server {
	return New(auth.NewManager("admin", "secret", time.Hour))
}

func do(t *testing.T, s *Server, method, path, body, token string) *httptest.ResponseRecorder {
	t.Helper()
	var reader *strings.Reader
	if body == "" {
		reader = strings.NewReader("")
	} else {
		reader = strings.NewReader(body)
	}
	req := httptest.NewRequest(method, path, reader)
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)
	return rec
}

func TestHealth(t *testing.T) {
	rec := do(t, newTestServer(), http.MethodGet, "/healthz", "", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("GET /healthz = %d，期望 200", rec.Code)
	}
	var got map[string]string
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatalf("healthz body 不是 JSON: %v", err)
	}
	if got["status"] != "ok" {
		t.Fatalf("healthz status = %q，期望 ok", got["status"])
	}
}

func TestLoginRejectsBadCredentials(t *testing.T) {
	rec := do(t, newTestServer(), http.MethodPost, "/api/v1/login",
		`{"username":"admin","password":"wrong"}`, "")
	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("错误密码登录 = %d，期望 401", rec.Code)
	}
}

func TestLoginAndMe(t *testing.T) {
	s := newTestServer()

	rec := do(t, s, http.MethodPost, "/api/v1/login",
		`{"username":"admin","password":"secret"}`, "")
	if rec.Code != http.StatusOK {
		t.Fatalf("正确凭据登录 = %d，期望 200", rec.Code)
	}
	var login struct {
		Token string `json:"token"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &login); err != nil {
		t.Fatalf("登录 body 不是 JSON: %v", err)
	}
	if login.Token == "" {
		t.Fatal("登录应返回非空 token")
	}

	rec = do(t, s, http.MethodGet, "/api/v1/me", "", login.Token)
	if rec.Code != http.StatusOK {
		t.Fatalf("带 token 访问 /api/v1/me = %d，期望 200", rec.Code)
	}
	var me map[string]string
	if err := json.Unmarshal(rec.Body.Bytes(), &me); err != nil {
		t.Fatalf("me body 不是 JSON: %v", err)
	}
	if me["username"] != "admin" {
		t.Fatalf("me username = %q，期望 admin", me["username"])
	}
}

func TestProtectedRouteRequiresToken(t *testing.T) {
	s := newTestServer()

	for _, token := range []string{"", "bogus"} {
		rec := do(t, s, http.MethodGet, "/api/v1/me", "", token)
		if rec.Code != http.StatusUnauthorized {
			t.Fatalf("token=%q 访问受保护路由 = %d，期望 401", token, rec.Code)
		}
	}
}

