// Package store 提供用户资源的文件持久化仓库。
package store

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

// 仓库返回的哨兵错误。
var (
	ErrNotFound = errors.New("用户不存在")
	ErrConflict = errors.New("用户名已存在")
	ErrInvalid  = errors.New("用户字段非法")
)

// User 是后台管理里的用户资源。
type User struct {
	ID          string    `json:"id"`
	Username    string    `json:"username"`
	DisplayName string    `json:"display_name"`
	Role        string    `json:"role"`
	Active      bool      `json:"active"`
	CreatedAt   time.Time `json:"created_at"`
	UpdatedAt   time.Time `json:"updated_at"`
}

// Update 是局部更新；nil 字段表示不改。
type Update struct {
	DisplayName *string `json:"display_name"`
	Role        *string `json:"role"`
	Active      *bool   `json:"active"`
}

// Store 是并发安全、JSON 文件持久化的用户仓库。
type Store struct {
	path  string
	mu    sync.Mutex
	users map[string]*User
}

// Open 打开数据文件；文件不存在时从空仓库开始，父目录会自动创建。
func Open(path string) (*Store, error) {
	s := &Store{path: path, users: make(map[string]*User)}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return nil, fmt.Errorf("创建数据目录: %w", err)
	}
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return s, nil
	}
	if err != nil {
		return nil, fmt.Errorf("读取数据文件: %w", err)
	}
	if len(strings.TrimSpace(string(data))) == 0 {
		return s, nil
	}
	var file struct {
		Users []User `json:"users"`
	}
	if err := json.Unmarshal(data, &file); err != nil {
		return nil, fmt.Errorf("解析数据文件: %w", err)
	}
	for i := range file.Users {
		user := file.Users[i]
		s.users[user.ID] = &user
	}
	return s, nil
}

// List 返回全部用户（按创建时间、再按 id 排序）。
func (s *Store) List() []User {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]User, 0, len(s.users))
	for _, user := range s.users {
		out = append(out, *user)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].ID < out[j].ID
		}
		return out[i].CreatedAt.Before(out[j].CreatedAt)
	})
	return out
}

// Get 按 id 返回用户；不存在返回 ErrNotFound。
func (s *Store) Get(id string) (User, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	user, ok := s.users[id]
	if !ok {
		return User{}, ErrNotFound
	}
	return *user, nil
}

// Create 新建用户；用户名（不区分大小写）重复返回 ErrConflict。
func (s *Store) Create(in User) (User, error) {
	in.Username = strings.TrimSpace(in.Username)
	if in.Username == "" {
		return User{}, fmt.Errorf("%w: username 不能为空", ErrInvalid)
	}
	if in.Role == "" {
		in.Role = "user"
	}
	if in.Role != "admin" && in.Role != "user" {
		return User{}, fmt.Errorf("%w: role 只能是 admin 或 user", ErrInvalid)
	}
	in.DisplayName = strings.TrimSpace(in.DisplayName)
	if in.DisplayName == "" {
		in.DisplayName = in.Username
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	for _, user := range s.users {
		if strings.EqualFold(user.Username, in.Username) {
			return User{}, ErrConflict
		}
	}

	now := time.Now().UTC()
	in.ID = newID()
	in.CreatedAt = now
	in.UpdatedAt = now
	stored := in
	s.users[stored.ID] = &stored
	if err := s.saveLocked(); err != nil {
		delete(s.users, stored.ID)
		return User{}, err
	}
	return stored, nil
}

// Update 局部更新用户；用户名不可改，id 不存在返回 ErrNotFound。
func (s *Store) Update(id string, patch Update) (User, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	user, ok := s.users[id]
	if !ok {
		return User{}, ErrNotFound
	}
	if patch.DisplayName != nil {
		user.DisplayName = strings.TrimSpace(*patch.DisplayName)
	}
	if patch.Role != nil {
		if *patch.Role != "admin" && *patch.Role != "user" {
			return User{}, fmt.Errorf("%w: role 只能是 admin 或 user", ErrInvalid)
		}
		user.Role = *patch.Role
	}
	if patch.Active != nil {
		user.Active = *patch.Active
	}
	user.UpdatedAt = time.Now().UTC()
	if err := s.saveLocked(); err != nil {
		return User{}, err
	}
	return *user, nil
}

// Delete 删除用户；id 不存在返回 ErrNotFound。
func (s *Store) Delete(id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	user, ok := s.users[id]
	if !ok {
		return ErrNotFound
	}
	delete(s.users, id)
	if err := s.saveLocked(); err != nil {
		s.users[id] = user
		return err
	}
	return nil
}

// saveLocked 原子地把整份仓库写回磁盘；调用方必须持有锁。
func (s *Store) saveLocked() error {
	list := make([]User, 0, len(s.users))
	for _, user := range s.users {
		list = append(list, *user)
	}
	sort.Slice(list, func(i, j int) bool { return list[i].ID < list[j].ID })

	data, err := json.MarshalIndent(struct {
		Users []User `json:"users"`
	}{list}, "", "  ")
	if err != nil {
		return fmt.Errorf("编码数据: %w", err)
	}

	tmp, err := os.CreateTemp(filepath.Dir(s.path), ".users-*.tmp")
	if err != nil {
		return fmt.Errorf("创建临时文件: %w", err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)

	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return fmt.Errorf("写临时文件: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("关闭临时文件: %w", err)
	}
	if err := os.Rename(tmpName, s.path); err != nil {
		return fmt.Errorf("替换数据文件: %w", err)
	}
	return nil
}

// newID 生成 128 位随机用户 id。
func newID() string {
	buf := make([]byte, 16)
	if _, err := rand.Read(buf); err != nil {
		panic("store: 无法生成随机 id: " + err.Error())
	}
	return hex.EncodeToString(buf)
}

package store

import (
