func openTemp(t *testing.T) (*Store, string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "users.json")
	s, err := Open(path)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	return s, path
}

func TestCreateGetList(t *testing.T) {
	s, _ := openTemp(t)

	created, err := s.Create(User{Username: "alice"})
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	if created.ID == "" {
		t.Fatal("Create 应生成非空 id")
	}
	if created.Role != "user" {
		t.Fatalf("默认 role = %q，期望 user", created.Role)
	}
	if created.DisplayName != "alice" {
		t.Fatalf("默认 display_name = %q，期望 alice", created.DisplayName)
	}

	got, err := s.Get(created.ID)
	if err != nil {
		t.Fatalf("Get: %v", err)
	}
	if got.Username != "alice" {
		t.Fatalf("Get username = %q，期望 alice", got.Username)
	}

	list := s.List()
	if len(list) != 1 || list[0].ID != created.ID {
		t.Fatalf("List = %+v，期望只含刚创建的用户", list)
	}
}

func TestCreateRejectsDuplicateUsername(t *testing.T) {
	s, _ := openTemp(t)
	if _, err := s.Create(User{Username: "alice"}); err != nil {
		t.Fatalf("首次 Create: %v", err)
	}
	if _, err := s.Create(User{Username: "ALICE"}); !errors.Is(err, ErrConflict) {
		t.Fatalf("重复用户名 err = %v，期望 ErrConflict", err)
	}
}

func TestCreateRejectsInvalid(t *testing.T) {
	s, _ := openTemp(t)
	if _, err := s.Create(User{Username: "  "}); !errors.Is(err, ErrInvalid) {
		t.Fatalf("空用户名 err = %v，期望 ErrInvalid", err)
	}
	if _, err := s.Create(User{Username: "bob", Role: "root"}); !errors.Is(err, ErrInvalid) {
		t.Fatalf("非法 role err = %v，期望 ErrInvalid", err)
	}
}

func TestUpdateAndDelete(t *testing.T) {
	s, _ := openTemp(t)
	created, _ := s.Create(User{Username: "alice"})

	name := "Alice A."
	active := false
	updated, err := s.Update(created.ID, Update{DisplayName: &name, Active: &active})
	if err != nil {
		t.Fatalf("Update: %v", err)
	}
	if updated.DisplayName != name || updated.Active {
		t.Fatalf("Update 结果 = %+v，期望 display_name=%q active=false", updated, name)
	}
	if !updated.UpdatedAt.After(created.UpdatedAt) && !updated.UpdatedAt.Equal(created.UpdatedAt) {
		t.Fatalf("UpdatedAt 不应早于 CreatedAt")
	}

	if _, err := s.Update("missing", Update{}); !errors.Is(err, ErrNotFound) {
		t.Fatalf("更新不存在 id err = %v，期望 ErrNotFound", err)
	}

	if err := s.Delete(created.ID); err != nil {
		t.Fatalf("Delete: %v", err)
	}
	if _, err := s.Get(created.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("删除后 Get err = %v，期望 ErrNotFound", err)
	}
	if err := s.Delete(created.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("重复删除 err = %v，期望 ErrNotFound", err)
	}
}

func TestPersistsAcrossReopen(t *testing.T) {
	s, path := openTemp(t)
	created, err := s.Create(User{Username: "alice", DisplayName: "Alice"})
	if err != nil {
		t.Fatalf("Create: %v", err)
	}

	reopened, err := Open(path)
	if err != nil {
		t.Fatalf("重新 Open: %v", err)
	}
	got, err := reopened.Get(created.ID)
	if err != nil {
		t.Fatalf("重开后 Get: %v", err)
	}
	if got.Username != "alice" || got.DisplayName != "Alice" {
		t.Fatalf("重开后读回 = %+v，期望 alice/Alice", got)
	}
}

// Package server 提供后台管理系统的 HTTP 路由与处理器。
package server

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"

	"admin/internal/auth"
	"admin/internal/store"
)

// maxBodyBytes 限制 JSON 请求体的大小，避免无界读取。
const maxBodyBytes = 1 << 20

// Server 组装路由并持有依赖。零值不可用，请用 New 构造。
type Server struct {
	auth  *auth.Manager
	store *store.Store
	mux   *http.ServeMux
}

// New 用给定依赖构造 Server 并注册路由。
func New(a *auth.Manager, st *store.Store) *Server {
	s := &Server{auth: a, store: st, mux: http.NewServeMux()}
	s.routes()
	return s
}

// ServeHTTP 让 Server 满足 http.Handler。
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	s.mux.ServeHTTP(w, r)
}

func (s *Server) routes() {
	s.mux.HandleFunc("/healthz", s.handleHealth)
	s.mux.HandleFunc("/api/v1/login", s.handleLogin)
	s.mux.Handle("/api/v1/", s.requireAuth(http.HandlerFunc(s.handleAPI)))
}

// handleHealth 是无需鉴权的健康检查。
func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

// handleLogin 校验管理员凭据并签发 bearer token。
func (s *Server) handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
		return
	}
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := decodeJSON(r, &req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid request body"})
		return
	}
	if !s.auth.Authenticate(req.Username, req.Password) {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid credentials"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"token": s.auth.Issue()})
}

// handleAPI 分发已通过鉴权的 /api/v1 请求。
func (s *Server) handleAPI(w http.ResponseWriter, r *http.Request) {
	switch {
	case r.URL.Path == "/api/v1/me":
		s.handleMe(w, r)
	case r.URL.Path == "/api/v1/users":
		s.handleUsers(w, r)
	case strings.HasPrefix(r.URL.Path, "/api/v1/users/"):
		s.handleUserByID(w, r)
	default:
		http.NotFound(w, r)
	}
}

// handleMe 返回当前登录的管理员身份。
func (s *Server) handleMe(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"username": s.auth.Username()})
}

// handleUsers 处理用户集合的列表与创建。
func (s *Server) handleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		writeJSON(w, http.StatusOK, map[string]any{"users": s.store.List()})
	case http.MethodPost:
		var in struct {
			Username    string `json:"username"`
			DisplayName string `json:"display_name"`
			Role        string `json:"role"`
			Active      *bool  `json:"active"`
		}
		if err := decodeJSON(r, &in); err != nil {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid request body"})
			return
		}
		user := store.User{
			Username:    in.Username,
			DisplayName: in.DisplayName,
			Role:        in.Role,
			Active:      true,
		}
		if in.Active != nil {
			user.Active = *in.Active
		}
		created, err := s.store.Create(user)
		if err != nil {
			writeStoreError(w, err)
			return
		}
		writeJSON(w, http.StatusCreated, created)
	default:
		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
	}
}

// handleUserByID 处理单个用户的读取、更新与删除。
func (s *Server) handleUserByID(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/api/v1/users/")
	if id == "" || strings.Contains(id, "/") {
		http.NotFound(w, r)
		return
	}
	switch r.Method {
	case http.MethodGet:
		user, err := s.store.Get(id)
		if err != nil {
			writeStoreError(w, err)
			return
		}
		writeJSON(w, http.StatusOK, user)
	case http.MethodPut:
		var patch store.Update
		if err := decodeJSON(r, &patch); err != nil {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid request body"})
			return
		}
		updated, err := s.store.Update(id, patch)
		if err != nil {
			writeStoreError(w, err)
			return
		}
		writeJSON(w, http.StatusOK, updated)
	case http.MethodDelete:
		if err := s.store.Delete(id); err != nil {
			writeStoreError(w, err)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	default:
		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
	}
}

// requireAuth 是校验 bearer token 的中间件，未通过一律 401。
func (s *Server) requireAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !s.auth.Valid(bearerToken(r)) {
			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
			return
		}
		next.ServeHTTP(w, r)
	})
}

// writeStoreError 把仓库哨兵错误映射成 HTTP 状态码。
func writeStoreError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "user not found"})
	case errors.Is(err, store.ErrConflict):
		writeJSON(w, http.StatusConflict, map[string]string{"error": "username already exists"})
	case errors.Is(err, store.ErrInvalid):
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	default:
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
	}
}

// decodeJSON 读取并解析受大小限制的 JSON 请求体。
func decodeJSON(r *http.Request, target any) error {
	return json.NewDecoder(io.LimitReader(r.Body, maxBodyBytes)).Decode(target)
}

// bearerToken 从 Authorization 头取出 bearer token，取不到返回空串。
func bearerToken(r *http.Request) string {
	const prefix = "Bearer "
	header := r.Header.Get("Authorization")
	if len(header) <= len(prefix) || !strings.EqualFold(header[:len(prefix)], prefix) {
		return ""
	}
	return strings.TrimSpace(header[len(prefix):])
}

// writeJSON 以 JSON 写出响应。
func writeJSON(w http.ResponseWriter, status int, payload any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(payload)
}

package server

import (
	"encoding/json"
