	"path/filepath"
	"strings"
	"testing"
	"time"

	"admin/internal/auth"
	"admin/internal/store"
)

func newTestServer(t *testing.T) *Server {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "users.json"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	return New(auth.NewManager("admin", "secret", time.Hour), st)
}

func do(t *testing.T, s *Server, method, path, body, token string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)
	return rec
}

func login(t *testing.T, s *Server) string {
	t.Helper()
	rec := do(t, s, http.MethodPost, "/api/v1/login",
		`{"username":"admin","password":"secret"}`, "")
	if rec.Code != http.StatusOK {
		t.Fatalf("登录 = %d，期望 200", rec.Code)
	}
	var login struct {
		Token string `json:"token"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &login); err != nil {
		t.Fatalf("登录 body 不是 JSON: %v", err)
	}
	return login.Token
}

func createUser(t *testing.T, s *Server, token, body string) store.User {
	t.Helper()
	rec := do(t, s, http.MethodPost, "/api/v1/users", body, token)
	if rec.Code != http.StatusCreated {
		t.Fatalf("创建用户 = %d（body %s），期望 201", rec.Code, rec.Body.String())
	}
	var user store.User
	if err := json.Unmarshal(rec.Body.Bytes(), &user); err != nil {
		t.Fatalf("创建用户 body 不是 JSON: %v", err)
	}
	return user
}

func TestHealth(t *testing.T) {
	rec := do(t, newTestServer(t), http.MethodGet, "/healthz", "", "")
	if rec.Code != http.StatusOK {
		t.Fatalf("GET /healthz = %d，期望 200", rec.Code)
	}
	var got map[string]string
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatalf("healthz body 不是 JSON: %v", err)
	}
	if got["status"] != "ok" {
		t.Fatalf("healthz status = %q，期望 ok", got["status"])
	}
}

func TestLoginRejectsBadCredentials(t *testing.T) {
	rec := do(t, newTestServer(t), http.MethodPost, "/api/v1/login",
		`{"username":"admin","password":"wrong"}`, "")
	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("错误密码登录 = %d，期望 401", rec.Code)
	}
}

func TestLoginAndMe(t *testing.T) {
	s := newTestServer(t)
	token := login(t, s)

	rec := do(t, s, http.MethodGet, "/api/v1/me", "", token)
	if rec.Code != http.StatusOK {
		t.Fatalf("带 token 访问 /api/v1/me = %d，期望 200", rec.Code)
	}
	var me map[string]string
	if err := json.Unmarshal(rec.Body.Bytes(), &me); err != nil {
		t.Fatalf("me body 不是 JSON: %v", err)
	}
	if me["username"] != "admin" {
		t.Fatalf("me username = %q，期望 admin", me["username"])
	}
}

func TestProtectedRouteRequiresToken(t *testing.T) {
	s := newTestServer(t)
	for _, token := range []string{"", "bogus"} {
		rec := do(t, s, http.MethodGet, "/api/v1/me", "", token)
		if rec.Code != http.StatusUnauthorized {
			t.Fatalf("token=%q 访问受保护路由 = %d，期望 401", token, rec.Code)
		}
	}
}

func TestUserCRUD(t *testing.T) {
	s := newTestServer(t)
	token := login(t, s)

	created := createUser(t, s, token, `{"username":"alice","display_name":"Alice"}`)
	if created.ID == "" {
		t.Fatal("创建应返回 id")
	}

	rec := do(t, s, http.MethodGet, "/api/v1/users", "", token)
	if rec.Code != http.StatusOK {
		t.Fatalf("列表 = %d，期望 200", rec.Code)
	}
	if !strings.Contains(rec.Body.String(), `"username":"alice"`) {
		t.Fatalf("列表未包含 alice: %s", rec.Body.String())
	}

	rec = do(t, s, http.MethodGet, "/api/v1/users/"+created.ID, "", token)
	if rec.Code != http.StatusOK {
		t.Fatalf("读取单个 = %d，期望 200", rec.Code)
	}

	rec = do(t, s, http.MethodPut, "/api/v1/users/"+created.ID, `{"display_name":"Alice A."}`, token)
	if rec.Code != http.StatusOK {
		t.Fatalf("更新 = %d，期望 200", rec.Code)
	}
	if !strings.Contains(rec.Body.String(), `"display_name":"Alice A."`) {
		t.Fatalf("更新后 body = %s", rec.Body.String())
	}

	rec = do(t, s, http.MethodDelete, "/api/v1/users/"+created.ID, "", token)
	if rec.Code != http.StatusNoContent {
		t.Fatalf("删除 = %d，期望 204", rec.Code)
	}
	rec = do(t, s, http.MethodGet, "/api/v1/users/"+created.ID, "", token)
	if rec.Code != http.StatusNotFound {
		t.Fatalf("删除后读取 = %d，期望 404", rec.Code)
	}
}

func TestUserCreateConflictAndMissing(t *testing.T) {
	s := newTestServer(t)
	token := login(t, s)
	createUser(t, s, token, `{"username":"alice"}`)

	rec := do(t, s, http.MethodPost, "/api/v1/users", `{"username":"alice"}`, token)
	if rec.Code != http.StatusConflict {
		t.Fatalf("重复用户名创建 = %d，期望 409", rec.Code)
	}
	rec = do(t, s, http.MethodGet, "/api/v1/users/missing", "", token)
	if rec.Code != http.StatusNotFound {
		t.Fatalf("读取不存在 id = %d，期望 404", rec.Code)
	}
