package main

import (
	"log"
	"net/http"
	"os"
	"time"

	"admin/internal/auth"
	"admin/internal/server"
	"admin/internal/store"
)

func main() {
	addr := envOr("ADDR", ":8080")

	users, err := store.Open(envOr("DATA_FILE", "data/users.json"))
	if err != nil {
		log.Fatalf("打开数据文件失败: %v", err)
	}

	manager := auth.NewManager(
		envOr("ADMIN_USERNAME", "admin"),
		envOr("ADMIN_PASSWORD", "admin"),
		12*time.Hour,
	)

	log.Printf("admin 服务监听 %s", addr)
	if err := http.ListenAndServe(addr, server.New(manager, users)); err != nil {
		log.Fatalf("服务退出: %v", err)
	}
}

// envOr 读取环境变量，未设置时返回默认值。
func envOr(key, fallback string) string {
	if value := os.Getenv(key); value != "" {
		return value
	}
	return fallback
}

package server

import (
	"errors"
	"html/template"
	"net/http"

	"admin/internal/store"
)

// sessionCookie 是控制台会话 cookie 名，值就是 bearer token。
const sessionCookie = "admin_session"

// consoleView 是控制台模板的数据。
type consoleView struct {
	LoggedIn bool
	Users    []store.User
	Error    string
}

var consoleTemplate = template.Must(template.New("console").Parse(consoleHTML))

// handleConsole 处理控制台的页面与表单提交。
func (s *Server) handleConsole(w http.ResponseWriter, r *http.Request) {
	switch {
	case r.URL.Path == "/" && r.Method == http.MethodGet:
		s.handleConsoleIndex(w, r)
	case r.URL.Path == "/login" && r.Method == http.MethodPost:
		s.handleConsoleLogin(w, r)
	case r.URL.Path == "/logout" && r.Method == http.MethodPost:
		s.handleConsoleLogout(w, r)
	case r.URL.Path == "/users" && r.Method == http.MethodPost:
		s.handleConsoleCreateUser(w, r)
	default:
		http.NotFound(w, r)
	}
}

// handleConsoleIndex 已登录渲染用户管理页，否则渲染登录页。
func (s *Server) handleConsoleIndex(w http.ResponseWriter, r *http.Request) {
	if !s.auth.Valid(sessionToken(r)) {
		s.renderConsole(w, http.StatusOK, consoleView{})
		return
	}
	s.renderConsole(w, http.StatusOK, consoleView{LoggedIn: true, Users: s.store.List()})
}

// handleConsoleLogin 校验表单凭据，成功后种下会话 cookie。
func (s *Server) handleConsoleLogin(w http.ResponseWriter, r *http.Request) {
	if err := r.ParseForm(); err != nil {
		s.renderConsole(w, http.StatusBadRequest, consoleView{Error: "请求格式不正确"})
		return
	}
	if !s.auth.Authenticate(r.FormValue("username"), r.FormValue("password")) {
		s.renderConsole(w, http.StatusUnauthorized, consoleView{Error: "用户名或密码错误"})
		return
	}
	http.SetCookie(w, &http.Cookie{
		Name:     sessionCookie,
		Value:    s.auth.Issue(),
		Path:     "/",
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
	})
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

// handleConsoleLogout 清掉会话 cookie。
func (s *Server) handleConsoleLogout(w http.ResponseWriter, r *http.Request) {
	http.SetCookie(w, &http.Cookie{
		Name:     sessionCookie,
		Value:    "",
		Path:     "/",
		MaxAge:   -1,
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
	})
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

// handleConsoleCreateUser 处理控制台的新增用户表单。
func (s *Server) handleConsoleCreateUser(w http.ResponseWriter, r *http.Request) {
	if !s.auth.Valid(sessionToken(r)) {
		http.Redirect(w, r, "/", http.StatusSeeOther)
		return
	}
	if err := r.ParseForm(); err != nil {
		s.renderConsole(w, http.StatusBadRequest, consoleView{LoggedIn: true, Users: s.store.List(), Error: "请求格式不正确"})
		return
	}
	_, err := s.store.Create(store.User{
		Username:    r.FormValue("username"),
		DisplayName: r.FormValue("display_name"),
		Role:        r.FormValue("role"),
		Active:      r.FormValue("active") == "on",
	})
	if err != nil {
		status, message := http.StatusBadRequest, "创建失败："+err.Error()
		if errors.Is(err, store.ErrConflict) {
			status, message = http.StatusConflict, "创建失败：用户名已存在"
		}
		s.renderConsole(w, status, consoleView{LoggedIn: true, Users: s.store.List(), Error: message})
		return
	}
	http.Redirect(w, r, "/", http.StatusSeeOther)
}

// renderConsole 渲染控制台页面。
func (s *Server) renderConsole(w http.ResponseWriter, status int, view consoleView) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.WriteHeader(status)
	_ = consoleTemplate.Execute(w, view)
}

// sessionToken 从控制台 cookie 取出会话 token，取不到返回空串。
func sessionToken(r *http.Request) string {
	cookie, err := r.Cookie(sessionCookie)
	if err != nil {
		return ""
	}
	return cookie.Value
}

