func (s *Store) Update(id string, patch Update) (User, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	current, ok := s.users[id]
	if !ok {
		return User{}, ErrNotFound
	}

	updated := *current
	if patch.DisplayName != nil {
		updated.DisplayName = strings.TrimSpace(*patch.DisplayName)
