// Issue 签发一个新的会话 token 并记录其有效期；顺带清掉已过期的会话。
func (m *Manager) Issue() string {
	token := randomToken()
	now := time.Now()
	m.mu.Lock()
	defer m.mu.Unlock()
	for existing, expiresAt := range m.sessions {
		if now.After(expiresAt) {
			delete(m.sessions, existing)
		}
	}
	m.sessions[token] = now.Add(m.ttl)
	return token
}

// Revoke 立即失效一个会话 token（登出用）。
func (m *Manager) Revoke(token string) {
	if token == "" {
		return
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	delete(m.sessions, token)
}

